export class LimitOfSumUnderstandExperience{constructor(host){this.host=host;this.document=host.ownerDocument||document;this.explorer=null;}supports(id){return ids.has(id);}destroy(){this.explorer?.destroy();this.explorer=null;this.host.replaceChildren();this.host.classList.remove('limit-of-sum-understand');}render(id){if(!this.supports(id))return false;this.destroy();this.host.classList.add('limit-of-sum-understand');this.renderPanel(id.split(':').at(-1));return true;}panel(t,e,b){const p=el(this.document,'section','limit-of-sum-understand__panel');const h=el(this.document,'header','limit-of-sum-understand__header');h.append(el(this.document,'span','limit-of-sum-understand__eyebrow',e),el(this.document,'h3','',t),el(this.document,'p','',b));p.append(h);this.host.append(p);return p;}mount(p,n=4){const h=el(this.document,'div','limit-of-sum-understand__explorer');p.append(h);this.explorer=new RectangleSumExplorer(h,{initialFunctionId:'rectangle-positive-quadratic',initialLower:0,initialUpper:2,initialN:n,initialSampleLocation:'right',showFunctionSelector:false,maxRectangles:100});return this.explorer;}renderPanel(slug){if(slug==='rectangle-progression'){const p=this.panel('From one rectangle to a finite sum','Plan 35 · Rectangles','Each strip contributes approximately f(xₖ)Δx. Use the control to compare one rectangle with several.');const ex=this.mount(p,1);const row=el(this.document,'div','limit-of-sum-understand__buttons');[1,4,12].forEach(n=>{const b=el(this.document,'button','limit-of-sum-understand__button',`${n} rectangle${n===1?'':'s'}`);b.type='button';b.onclick=()=>ex.setRectangleCount(n);row.append(b)});p.append(row);return;}if(slug==='thinner-rectangles'){const p=this.panel('Thinner rectangles approach the exact integral','Plan 35 · Limit idea','As n increases, Δx shrinks and the finite rectangle sum approaches the definite integral.');const ex=this.mount(p,4);const out=el(this.document,'div','limit-of-sum-understand__formula');const update=()=>{const s=ex.getRectangleState();out.textContent=`n=${s.n}; Δx=${s.deltaX.toFixed(3)}; rectangle sum=${s.sum.toFixed(4)}; integral target=${s.exactIntegral.toFixed(4)}`};[4,10,25,80].forEach(n=>{const b=el(this.document,'button','limit-of-sum-understand__button',`n=${n}`);b.type='button';b.onclick=()=>{ex.setRectangleCount(n);update()};p.append(b)});p.append(out);update();return;}if(slug==='sum-to-integral'){const p=this.panel('Sum → Integral highlighter','Plan 35 · Recognition','Map each component before doing any integration. Select a piece of the limiting sum to see its destination.');const ex=this.mount(p,8);const map=buildSumToIntegralMap(ex.getRectangleState(),ex.definition);const grid=el(this.document,'div','limit-of-sum-understand__map');[['height','f(xₖ)','integrand f(x)'],['width','Δx','dx'],['lower','a','lower limit'],['upper','b','upper limit']].forEach(([id,a,b])=>{const bt=el(this.document,'button','limit-of-sum-understand__map-button',`${a} → ${b}`);bt.type='button';bt.onclick=()=>{grid.querySelectorAll('.is-active').forEach(x=>x.classList.remove('is-active'));bt.classList.add('is-active')};grid.append(bt)});p.append(grid,el(this.document,'div','limit-of-sum-understand__formula',`${map.limitingSum}  →  ${map.integral}`),el(this.document,'p','limit-of-sum-understand__note',`${map.integrand}; ${map.lowerBound}; ${map.upperBound}; ${map.sample}`));return;}if(slug==='k-notation'){const p=this.panel('k-notation is just rectangle bookkeeping','Plan 35 · Brief notation','Do not turn this into a separate theory topic: k labels the rectangle, Δx is its width, and xₖ selects the sample point.');this.mount(p,6);const k=buildKNotation({a:0,b:2});p.append(el(this.document,'div','limit-of-sum-understand__steps',`${k.width}   •   ${k.sample}   •   ${k.finite}   •   ${k.integral}`));return;}if(slug==='recognise-first'){const p=this.panel('Recognition comes before evaluation','Plan 35 · Exam skill','For a limiting sum, first state only the integrand and limits. Do not integrate yet.');const e=LIMIT_OF_SUM_EXAMPLES[0];p.append(el(this.document,'div','limit-of-sum-understand__formula',e.sum),el(this.document,'div','limit-of-sum-understand__cards',`Integrand: ${e.integrand}   |   limits: ${e.lower} to ${e.upper}   |   integral: ${e.integral}`));return;}const p=this.panel('Recognise first; technique second','Plan 35 · Complete question','Once the definite integral is identified, use the existing integration toolkit rather than inventing a special limit-of-sum calculation method.');for(const e of LIMIT_OF_SUM_EXAMPLES){const c=el(this.document,'article','limit-of-sum-understand__card');c.append(el(this.document,'strong','',e.sum),el(this.document,'p','',`${e.integral} → ${e.laterMethod} → ${e.value}`));p.append(c)}}}
